      .trigger:hover {
        filter: brightness(1.05);
        transform: translateY(-1px);
      }

      .trigger:focus-visible,
      .modal button:focus-visible {
        outline: 2px solid var(--accent);
        outline-offset: 2px;
      }

      .dialog-backdrop {
        position: fixed;
        inset: 0;
