        flex: 0 0 auto;
      }

      .modal h2 {
        margin: 0;
        font-size: 1.1rem;
      }

      .modal p {
        margin: 10px 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .actions {
        margin-top: 22px;
        display: flex;
        justify-content: flex-end;
        gap: 12px;
      }

      .secondary,
      .danger {
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.85rem 1rem;
        cursor: pointer;
      }

      .secondary {
        background: rgba(148, 163, 184, 0.12);
        color: var(--text);
        border-color: rgba(148, 163, 184, 0.16);
      }

      .danger {
        background: linear-gradient(180deg, var(--danger), var(--danger-strong));
        color: white;
        font-weight: 700;
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const state = {
        open: false,
      };

      const imageData = {
        title: "Sunset Ridge",
        subtitle: "Preview image in your library",
        src: "https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=80",
        alt: "Mountain landscape at sunset",
      };

      const root = document.getElementById("root");

      function ImagePreview({ onDelete }) {
        return `
          <main class="app">
            <section class="card" aria-labelledby="preview-title">
              <div class="preview">
                <div class="image-frame">
                  <img src="${imageData.src}" alt="${imageData.alt}" />
                </div>
                <div class="meta">
                  <div>
                    <h1 class="title" id="preview-title">${imageData.title}</h1>
                    <p class="subtitle">${imageData.subtitle}</p>
                  </div>
                  <button class="trigger" type="button" data-action="open-dialog">Delete</button>
                </div>
              </div>
            </section>
          </main>
        `;
      }

      function ConfirmDeleteDialog({ open }) {
        return `
          <div class="dialog-backdrop ${open ? "open" : ""}" data-action="backdrop" aria-hidden="${!open}">
            <div
              class="modal"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
            >
              <div class="modal-header">
                <div class="icon" aria-hidden="true">
                  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z"></path>
                    <path d="M12 9v4"></path>
                    <path d="M12 17h.01"></path>
                  </svg>
                </div>
                <div>
                  <h2 id="dialog-title">Delete this image?</h2>
                  <p id="dialog-description">
                    This will remove the image from your library. This action cannot be undone.
                  </p>
                </div>
              </div>
              <div class="actions">
                <button class="secondary" type="button" data-action="close-dialog">Cancel</button>
                <button class="danger" type="button" data-action="confirm-delete">Delete image</button>
              </div>
            </div>
          </div>
        `;
      }

      function App() {
        return `
          ${ImagePreview({})}
          ${ConfirmDeleteDialog({ open: state.open })}
        `;
      }

      function render() {
        root.innerHTML = App();
      }

      function setOpen(nextOpen) {
        state.open = nextOpen;
        render();
      }

      root.addEventListener("click", (event) => {
        const action = event.target.closest("[data-action]")?.dataset.action;
        if (!action) return;

        if (action === "open-dialog") setOpen(true);
        if (action === "close-dialog") setOpen(false);
        if (action === "backdrop") {
          if (event.target.matches("[data-action='backdrop']")) setOpen(false);
        }
        if (action === "confirm-delete") {
          setOpen(false);
        }
      });

      render();
    </script>
  </body>
</html>
